INSERT INTO `BlogPost` VALUES (8,'2023-01-17 12:20:06',NULL,NULL,1771,'Deine 120 Sekunden beginnen... JETZT! '),(9,'2023-01-18 12:06:31',NULL,NULL,1772,'Eine perfekte Präsentation - geht das?'),(10,'2023-01-18 12:25:57',NULL,NULL,1773,'Ohne dich/euch geht es nicht!'),(13,'2022-10-24 10:47:01',NULL,NULL,1784,'Damit deine Kundendaten dort bleiben, wo sie hingehören, nämlich bei DIR!'),(14,'2022-06-27 08:19:42',NULL,NULL,1790,'Habe den Mut und trau\' dich!'),(15,'2022-05-03 09:09:05',NULL,NULL,1810,'Alles was du brauchst, hast du in deiner Hosentasche! '),(16,'2022-02-23 09:25:24',NULL,NULL,1815,'Soziale Medien zeiteffizient und erfolgreich nutzen'),(17,'2022-01-03 08:27:16',NULL,NULL,1823,'Wir wollten einen Wohlfühlort für unsere PatientInnen schaffen.'),(18,'2023-02-01 10:45:27',NULL,NULL,1829,'Be the master of yourself! '),(19,'2016-09-02 08:00:00',NULL,NULL,1832,'Wir wollen euch die EPU-Szene in Niederösterreich näher bringen. '),(20,'2023-02-24 10:08:39',NULL,NULL,1846,'Ich würde sicher wieder mitmachen! '),(21,'2023-03-07 11:21:49',NULL,NULL,1864,'Ich weiß, warum ich jeden Tag aufstehe! '),(23,'2023-03-16 07:00:39',NULL,NULL,1884,'Praktisches Zeit- und Stressmanagement für den EPU-Alltag'),(24,'2023-10-04 09:48:26',NULL,NULL,0,NULL),(25,'2023-03-23 10:44:00',NULL,NULL,1892,'Der Osterhase hat tolle Geschenke aus Niederösterreich versteckt!'),(26,'2023-05-04 08:35:05',NULL,NULL,1914,'Selbständig schmerzfrei! - Präventives Gesundheitstraining für deinen EPU-Alltag inkl. praktischer Übungen'),(29,'2023-06-13 06:27:27',NULL,NULL,1946,'„Eine Frau kann alles sein, was sie will!“'),(30,'2023-07-07 08:23:12',NULL,'<p>Andrea Röcklinger ist&nbsp;Psychologische Beraterin (LSB),&nbsp;Systemische Trainerin,&nbsp;Glückstrainerin und&nbsp;Sozialpädagogin. In ihrem Blogbeitrag beschreibt sie, wie du mit Leichtigkeit glücklich durch deinen Business-Alltag kommst.</p>',1978,'Hallo, du Sonnenschein! '),(31,'2023-08-02 07:00:00',NULL,NULL,2022,'„Mit Speed zum Erfolg: Wie deine WordPress-Website zur Formel-1 unter den Webseiten wird!“'),(33,'2023-08-25 10:26:39',NULL,'<p>KI definiert die Art und Weise wie wir agieren neu! Die Möglichkeiten für EPU sind schier endlos: Von besseren Texten bis zu hochwertigen Fotos - KI generiert Lösungen für deine alltäglichen Aufgaben.</p>',2031,'Willkommen in der Ära der Künstlichen Intelligenz! '),(34,'2023-08-31 06:32:34',NULL,NULL,2028,'Erfolg heißt, dass ich in meinem Leben aus ganzem Herzen das tun kann, was ich möchte!'),(35,'2023-11-13 09:50:42',NULL,NULL,2096,'So bleibt dein Online-Meeting im Gedächtnis!'),(36,'2023-11-27 08:57:00',NULL,'<p>Von 1. bis 24. Dezember 2023 werden täglich zwei Geschenke im Wert von je € 150,- verlost!</p>',2107,'Weihnachten aus Niederösterreich!'),(37,'2024-01-09 08:40:16',NULL,NULL,2132,'Vertraue dir selbst! - Du kannst es!'),(39,'2024-04-18 09:13:00',NULL,NULL,2359,'Ich schätze die Rückmeldungen!'),(40,'2024-03-12 10:58:16',NULL,NULL,2317,'Wir lachen nicht, weil wir glücklich sind, wir sind glücklich, weil wir lachen.'),(42,'2024-06-05 10:15:24',NULL,NULL,2457,'Ein-Personen-Unternehmen trafen sich im Haus der Regionen in Krems'),(43,'2024-06-17 08:43:25',NULL,NULL,2484,'Selbstsichere und mutige Social Media Auftritte.'),(44,'2024-09-05 08:45:44',NULL,NULL,2555,'Entdecke deine Möglichkeiten!'),(45,'2024-09-19 08:53:08',NULL,NULL,2556,'Schon umgestellt?'),(47,'2024-10-03 11:18:00',NULL,NULL,2596,'So triffst du den perfekten Ton'),(48,'2024-11-27 09:32:00',NULL,NULL,2653,'Weihnachten in Niederösterreich'),(49,'2024-11-13 10:08:18',NULL,NULL,2656,'Kreislaufwirtschaft? Klingt kryptisch? '),(50,'2025-02-11 08:59:07',NULL,NULL,2777,'„Jo, was geht?“ '),(51,'2025-03-12 10:04:05',NULL,NULL,2819,'Keine Panik – kein Perfektionismus!'),(52,NULL,NULL,NULL,0,NULL),(53,'2025-03-14 09:25:00',NULL,NULL,2820,'Du hast nichts zu verlieren, du kannst nur gewinnen!'),(54,NULL,NULL,NULL,0,NULL),(55,'2025-05-07 11:09:00',NULL,NULL,2914,'Konsistent und professionell auftreten - von Anfang an!');
