  `Title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Tagline` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `CanViewType` enum('Anyone','LoggedInUsers','OnlyTheseUsers') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Anyone',
  `CanEditType` enum('LoggedInUsers','OnlyTheseUsers') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'LoggedInUsers',
  `CanCreateTopLevelType` enum('LoggedInUsers','OnlyTheseUsers') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'LoggedInUsers',
  `RegAfterText` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `RegEmailTitle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `RegEmailText` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `RegMailPublicTitle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `RegMailPublicText` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `RegMailOneDayTitle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `RegMailOneDayText` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `RegAdminEmailTitle` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `RegAdminEmailText` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `RegAllreadyRegistered` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`ID`),
