INSERT INTO `SiteConfig` VALUES (1,'SilverStripe\\SiteConfig\\SiteConfig','2023-02-28 13:03:35','2023-01-03 19:45:44','Wir Sind 1','Ein-Personen-Unternehmen in Niederösterreich','Anyone','LoggedInUsers','LoggedInUsers','<p>Vielen Dank für deinen Eintrag im Wir sind 1 EPU-Netzwerk! Im Sinne der Qualitätssicherung wird dein Profil vor der Freigabe noch überprüft. Du bekommst natürlich eine E-Mail, sobald dein Profil freigeschaltet ist.</p><p>Liebe Grüße vom<br>Team Wir sind 1</p><p>&nbsp;</p>','Vielen Dank für deinen Eintrag im EPU-Netzwerk!','<p class=\"right\" style=\"padding-left: 383px;\"><a class=\"ss-broken\" title=\"Webseite Wir sind 1\" rel=\"noopener noreferrer\" href=\"http://www.wirsind1.at\" target=\"_blank\"><img class=\"leftAlone ss-htmleditorfield-file image\" src=\"http://wirsind1.at/assets/Signatur/logo-jpg.jpg\" alt=\"\" width=\"217\" height=\"59\"></a></p><p>Hallo [NAME],</p><p>vielen Dank für deinen Eintrag im Wir sind 1 EPU-Netzwerk!</p><p>Im Sinne der Qualitätssicherung wird dein Profil vor der Freigabe noch überprüft. <br>Du bekommst natürlich eine E-Mail, sobald dein Profil freigeschaltet ist.</p><p>&nbsp;</p><p>Liebe Grüße vom<br>Team Wir sind 1</p><p><a class=\"ss-broken\" title=\"Webseite Wir sind 1\" rel=\"noopener noreferrer\" href=\"http://www.wirsind1.at\" target=\"_blank\"><img class=\"leftAlone ss-htmleditorfield-file image\" src=\"http://wirsind1.at/assets/Signatur/E-Mail-Banner-2023.jpg\" alt=\"Banner Wir sind 1\" width=\"600\" height=\"145\"></a></p><p><br><strong>Team Wir sind 1</strong><br>Prof. Dr. Stephan Koren-Straße 10<br>A-2700 Wiener Neustadt<br>E-Mail: team@wirsind1.at<br>Homepage: www.wirsind1.at<br>Telefon: +43/ 2622 / 263 26 0</p>','Dein Profil ist jetzt online!','<p class=\"right\" style=\"padding-left: 383px;\"><a class=\"ss-broken\" title=\"Webseite Wir sind 1\" rel=\"noopener noreferrer\" href=\"http://www.wirsind1.at\" target=\"_blank\"><img class=\"leftAlone ss-htmleditorfield-file image\" src=\"http://wirsind1.at/assets/Signatur/logo-jpg.jpg\" alt=\"\" width=\"217\" height=\"59\"></a></p><p>Hallo [NAME],</p><p>vielen Dank für deinen Eintrag im EPU-Netzwerk!</p><p>Wir haben dein Profil auf <a title=\"Wir sind 1 EPU-Netzwerk\" rel=\"noopener noreferrer\" href=\"https://www.wirsind1.at/epu-netzwerk\" target=\"_blank\">Wir sind 1</a> soeben freigeschaltet.</p><p>Wenn du deinen Eintrag irgendwann updaten möchtest, <br>melde dich bitte per E-Mail bei uns!</p><p>Liebe Grüße vom<br>Team Wir sind 1</p><p><a class=\"ss-broken\" title=\"Webseite Wir sind 1\" rel=\"noopener noreferrer\" href=\"http://www.wirsind1.at\" target=\"_blank\">[image src=\"/assets/Signatur/E-Mail-Banner-2023.jpg\" id=\"1794\" width=\"600\" height=\"145\" class=\"leftAlone ss-htmleditorfield-file image\"]</a></p><p><br><strong>Team Wir sind 1</strong><br>Prof. Dr. Stephan Koren-Straße 10<br>A-2700 Wiener Neustadt<br>E-Mail: team@wirsind1.at<br>Homepage: www.wirsind1.at<br>Telefon: +43/ 2622 / 263 26 0</p><p>&nbsp;</p>','Herzlich willkommen bei Wir sind 1!','<p class=\"right\" style=\"padding-left: 383px;\"><a class=\"ss-broken\" title=\"Webseite Wir sind 1\" rel=\"noopener noreferrer\" href=\"http://www.wirsind1.at\" target=\"_blank\"><img class=\"leftAlone ss-htmleditorfield-file image\" src=\"http://wirsind1.at/assets/Signatur/logo-jpg.jpg\" alt=\"\" width=\"217\" height=\"59\"></a></p><p>Hallo [NAME],</p><p>schön, dass du jetzt Teil der Wir sind 1 Community bist! Ab sofort kannst auch du dich mit den Ein-Personen-UnternehmerInnen auf <a class=\"ss-broken\" title=\"Webseite Wir sind 1\" rel=\"noopener noreferrer\" href=\"http://www.wirsind1.at\" target=\"_blank\">www.wirsind1.at</a> <strong>austauschen</strong> und <strong>vernetzen</strong>!<br> <br>Die Ein-Personen-Unternehmen (EPU) in Niederösterreich leisten jeden Tag großartige Dinge! Durch Wir sind 1 ist es möglich, das zu zeigen und so <strong>Niederösterreich</strong> zum <strong>Leuchtturm der EPU-Szene</strong> zu machen!<br> <br>Ich bin Michaela und für die Betreuung der Community, also auch für dich (innerhalb von Wir sind 1 sind wir \"per du\" - ich hoffe, das ist ok für dich?) zuständig. Wenn du Fragen oder Anregungen hast, kannst du dich gerne an mich wenden!<br> <br><strong>Kennst du noch andere EPU aus Niederösterreich?</strong> Dann erzähl\' ihnen von Wir sind 1 und lade sie ein, sich auf Wir sind 1 zu zeigen und von ihrer Erfolgsgeschichte als UnternehmerIn zu erzählen. Ich würde mich freuen!</p><p>Vielen Dank und herzliche Grüße<br>Michaela</p><p><a class=\"ss-broken\" title=\"Webseite Wir sind 1\" rel=\"noopener noreferrer\" href=\"http://www.wirsind1.at\" target=\"_blank\">[image src=\"/assets/Signatur/E-Mail-Banner-2023.jpg\" id=\"1794\" width=\"600\" height=\"145\" class=\"leftAlone ss-htmleditorfield-file image\"]</a></p><p><br><strong>Team Wir sind 1</strong><br>Prof. Dr. Stephan Koren-Straße 10<br>A-2700 Wiener Neustadt<br>E-Mail: team@wirsind1.at<br>Homepage: www.wirsind1.at<br>Telefon: +43/ 2622 / 263 26 0</p>','Neues Profil','<p>Hallöchen,</p><p>jipie - es gibt schon wieder einen neuen Eintrag im EPU-Netzwerk! :-)</p>','<p>Du hast dich in der Vergangenheit bereits im System registriert.&nbsp;</p><p>Du kannst dich nun mit einer neuen E-Mail Adresse anmelden oder deinen bestehenden Eintrag ändern. Dazu schreib\' bitte eine E-Mail mit deinen Änderungswünschen an team@wirsind1.at&nbsp; &nbsp;</p><p>Vielen Dank!</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p>');
/*!40000 ALTER TABLE `SiteConfig` ENABLE KEYS */;
UNLOCK TABLES;

